# The session's toy problem L(w1, w2) = w1^2 + 4 w2^2 from (4, 2): GD, momentum, Nesterov, AdaGrad, RMSprop, Adam, AdamW
import numpy as np
L = lambda w: w[0]**2 + 4*w[1]**2
grad = lambda w: np.array([2*w[0], 8*w[1]])
def run(step, n=3, w0=(4., 2.), **kw):
    w = np.array(w0); st = {}; rows = []
    for t in range(n + 1):
        g = grad(w); rows.append((t, L(w), g.copy(), w.copy()))
        if t < n: w = step(w, g, st, t + 1, **kw)
    return rows, w
def show(name, rows, w):
    print(f"--- {name}")
    for t, l, g, ww in rows: print(f"  iter {t}: w = ({ww[0]:.3f}, {ww[1]:.3f})  loss {l:.2f}  grad ({g[0]:.2f}, {g[1]:.2f})")
def gd(w, g, st, t, eta): return w - eta * g
def momentum(w, g, st, t, eta, beta=0.9):
    st["v"] = beta * st.get("v", 0) + g; return w - eta * st["v"]
def nesterov(w, g, st, t, eta, beta=0.9):
    v = st.get("v", np.zeros(2)); gl = grad(w - eta * beta * v); st["v"] = beta * v + gl; return w - eta * st["v"]
def adagrad(w, g, st, t, eta, eps=1e-8):
    st["s"] = st.get("s", 0) + g * g; return w - eta / np.sqrt(st["s"] + eps) * g
def rmsprop(w, g, st, t, eta, gamma=0.9, eps=1e-8):
    st["s"] = gamma * st.get("s", 0) + (1 - gamma) * g * g; return w - eta / np.sqrt(st["s"] + eps) * g
def adam(w, g, st, t, eta, b1=0.9, b2=0.999, eps=1e-8, wd=0.0):
    st["m"] = b1 * st.get("m", 0) + (1 - b1) * g; st["v"] = b2 * st.get("v", 0) + (1 - b2) * g * g
    mh = st["m"] / (1 - b1**t); vh = st["v"] / (1 - b2**t); return w - eta * (mh / (np.sqrt(vh) + eps) + wd * w)
show("mini-batch GD, eta=0.1 ", *run(gd, eta=0.1))
show("momentum, eta=0.05, beta=0.9 ", *run(momentum, eta=0.05))
show("RMSprop, eta=0.05 ", *run(rmsprop, eta=0.05))
show("Adam, eta=0.05 ", *run(adam, eta=0.05))
print("\nAfter 100 iterations (eta as above):")
for name, f, kw in [("GD 0.1", gd, dict(eta=0.1)), ("momentum 0.05", momentum, dict(eta=0.05)), ("Nesterov 0.05", nesterov, dict(eta=0.05)),
                    ("AdaGrad 0.5", adagrad, dict(eta=0.5)), ("RMSprop 0.05", rmsprop, dict(eta=0.05)), ("Adam 0.05", adam, dict(eta=0.05)), ("AdamW 0.05, wd 0.01", adam, dict(eta=0.05, wd=0.01))]:
    rows, w = run(f, n=100, **kw); print(f"  {name:20s} loss {L(w):.2e}  w = ({w[0]:.4f}, {w[1]:.4f})")
print("\nStability limit for plain GD: eta < 2/lambda_max = 2/8 =", 2/8)
